-- ─────────────────────────────────────────────────────────
-- A-2: Fix suction PSI thresholds in pak_diagnostic_questions
-- R-410A high_min = 145 (was incorrect, routing 130 PSI → HIGH)
-- ─────────────────────────────────────────────────────────

UPDATE pak_diagnostic_questions
SET branch_logic_jsonb = jsonb_set(
  branch_logic_jsonb,
  '{thresholds}',
  '{
    "R-32":   {"low_max": 120, "normal_min": 120, "normal_max": 140, "high_min": 141},
    "R-410A": {"low_max": 124, "normal_min": 125, "normal_max": 145, "high_min": 146},
    "R-22":   {"low_max": 64,  "normal_min": 65,  "normal_max": 88,  "high_min": 89},
    "not_sure": {"low_max": 64, "normal_min": 65, "normal_max": 145, "high_min": 146}
  }'::jsonb,
  true
)
WHERE complaint_type = 'not_cooling'
  AND (step_id ILIKE '%suction%' OR step_id ILIKE '%psi%' OR step_id ILIKE '%pressure%');

-- Verify: SELECT step_id, branch_logic_jsonb->'thresholds' FROM pak_diagnostic_questions
-- WHERE complaint_type = 'not_cooling' AND (step_id ILIKE '%suction%' OR step_id ILIKE '%psi%');


-- ─────────────────────────────────────────────────────────
-- B-3: Fix voltage thresholds in pak_diagnostic_questions
-- PK normal voltage: 190–260V (220V ±10%)
-- ─────────────────────────────────────────────────────────

UPDATE pak_diagnostic_questions
SET branch_logic_jsonb = jsonb_set(
  branch_logic_jsonb,
  '{thresholds}',
  '{
    "low_max": 189,
    "normal_min": 190,
    "normal_max": 260,
    "high_min": 261
  }'::jsonb,
  true
)
WHERE complaint_type = 'not_turning_on'
  AND (step_id ILIKE '%voltage%' OR step_id ILIKE '%contactor%' OR step_id ILIKE '%volts%');


