UPDATE pak_operating_targets
SET charging_targets = '{"_title": "Ready-to-insert JSON template per unit in database", "_note": "Copy the appropriate block into each series entry. Select by refrigerant + metering device type.", "R22_capillary_tube_standard": {"charging_targets": {"metering_device": "capillary_tube", "charging_method": "superheat", "superheat_target_c": 5, "superheat_target_f": 9, "superheat_range_c": "4–7", "superheat_range_f": "7–13", "subcooling_target_c": 5, "subcooling_target_f": 9, "subcooling_note": "Reference check only — not a primary charging target for capillary systems", "notes": "Target at 35°C outdoor ambient, typical Pakistan humid indoor conditions. Decrease superheat target by ~1°C (2°F) per 5°C above 35°C ambient. At 45°C ambient, target is 3°C / 5°F. Source: AC Service Tech target superheat formula + HVAC School 5 Pillars."}}, "R22_txv_premium": {"charging_targets": {"metering_device": "txv", "charging_method": "subcooling", "subcooling_target_c": 5, "subcooling_target_f": 9, "subcooling_range_c": "4–8", "subcooling_range_f": "7–14", "superheat_target_c": 5, "superheat_target_f": 9, "notes": "TXV systems — charge by subcooling. TXV maintains superheat automatically at 5–15°F. Applies to: Daikin FTKM/FTKC, Mitsubishi MSZ-GR, select Panasonic Tropical series. At 35°C ambient. Source: HVAC School 5 Pillars."}}, "R410A_txv_or_piston": {"charging_targets": {"metering_device": "txv_or_piston", "charging_method": "subcooling", "subcooling_target_c": 5, "subcooling_target_f": 9, "subcooling_range_c": "4–8", "subcooling_range_f": "7–14", "superheat_target_c": 5, "superheat_target_f": 9, "notes": "Applies to Gree GWC and Haier HSU R-410A fixed-speed series. At 35°C ambient. Verify metering device type from unit nameplate before charging. R-410A: never mix with R-22 equipment or charging hoses."}}}'::jsonb
WHERE id IS NOT NULL OR true
  RETURNING id;
-- If no rows updated, check table exists: SELECT * FROM pak_operating_targets LIMIT 1;


-- C-2: Seed fault_pressure_signatures into pak_operating_targets

UPDATE pak_operating_targets
SET fault_pressure_signatures = '{"_title": "Fault Pressure Signatures — Pakistan Climate (35–50°C Ambient)", "_reference_baselines_already_in_db": {"R-22": {"35C_ambient": {"suction_psi": "65–72", "discharge_psi": "250–275"}, "45C_ambient": {"suction_psi": "78–88", "discharge_psi": "310–345"}}, "R-32": {"35C_ambient": {"suction_psi": "125–135", "discharge_psi": "390–410"}, "45C_ambient": {"suction_psi": "150–165", "discharge_psi": "470–500"}}, "R-410A": {"35C_ambient": {"suction_psi": "115–125", "discharge_psi": "360–390"}}}, "_source": "HVAC School — ''The 5 Pillars of Residential A/C Refrigerant Circuit Diagnosis'' by Bryan Orr — https://hvacrschool.com/the-5-pillars-of-residential-ac-refrigerant-circuit-diagnosis/ | Confirmed against multiple HVAC-Talk and ACHR News sources", "_pakistan_high_ambient_note": "At 45–52°C ambient, baseline discharge pressures are already high. Fault thresholds shift accordingly. A ''dirty condenser'' discharge reading that would be 310 PSI at 35°C ambient could be 390+ PSI at 45°C ambient. Compressor high-pressure cutouts may trigger more frequently at extreme ambients even on properly charged systems.", "fault_pressure_signatures": {"R-22": {"low_charge": {"suction": "LOW", "discharge": "LOW", "superheat": "HIGH", "subcooling": "LOW", "delta_t": "LOW (poor cooling performance)", "threshold_35C": "Suction below 60 PSI, discharge below 230 PSI", "threshold_45C": "Suction below 72 PSI, discharge below 290 PSI", "notes": "Both gauges below baseline. Compressor is starved — evaporator frosting possible at extreme undercharge. Superheat high (typically >15°C / 27°F at evaporator). In Pakistan summer, leak-induced low charge is the #1 fault — refrigerant seeps through Schrader valves and flare joints due to thermal cycling.", "confidence": "HIGH"}, "dirty_condenser": {"suction": "SLIGHTLY_HIGH", "discharge": "HIGH", "superheat": "LOW_TO_NORMAL", "subcooling": "SLIGHTLY_HIGH", "delta_t": "LOW (reduced capacity)", "threshold_35C": "Discharge above 300 PSI (>10% above max baseline), suction slightly above 72 PSI", "threshold_45C": "Discharge above 370 PSI (>7% above max baseline), suction slightly above 90 PSI", "notes": "Cannot reject heat → high head. Heat recirculates to low side → suction slightly elevated. Superheat drops because higher saturation pressure raises evaporating temperature closer to actual suction line temp. Common in Pakistan: dust accumulation on condenser coil, birds/plastic bags blocking coil, or outdoor unit in a closed courtyard with no airflow. At 45–50°C ambient, a moderately dirty condenser can cause the compressor protector to trip.", "confidence": "HIGH"}, "overcharge": {"suction": "HIGH", "discharge": "HIGH", "superheat": "LOW_OR_ZERO", "subcooling": "HIGH", "delta_t": "LOW_TO_NORMAL", "threshold_35C": "Suction above 78 PSI, discharge above 300 PSI, subcooling >10°C", "threshold_45C": "Suction above 95 PSI, discharge above 370 PSI, subcooling >10°C", "notes": "Excessive refrigerant floods evaporator (liquid slugging risk to compressor) and backs up into condenser (high head). High subcooling confirms refrigerant backing up past condenser. Common in Pakistan when technicians ''top up'' systems without recovering first, or when using recycled refrigerant of unknown purity. Superheat at or near 0°C is a compressor-damaging condition.", "confidence": "HIGH"}, "dirty_evaporator_restricted_airflow": {"suction": "LOW", "discharge": "LOW_TO_NORMAL", "superheat": "HIGH", "subcooling": "NORMAL", "delta_t": "HIGH (large temp split, very cold supply, poor airflow volume)", "threshold_35C": "Suction below 62 PSI, discharge below 260 PSI, delta-T above 14°C", "threshold_45C": "Suction below 75 PSI, discharge below 310 PSI, delta-T above 14°C", "notes": "Less heat entering evaporator → lower evaporating pressure → low suction. Less heat to reject → lower discharge. Capillary tube still meters same refrigerant, but less heat available → HIGH superheat. Delta-T across evaporator coil is HIGH (supply air very cold but little airflow volume). Evaporator coil may ice up. In Pakistan: indoor filters become clogged with fine dust within 2–4 weeks in summer. Also: collapsed indoor unit drain pan, foam insulation pulled against blower, undersized or kinked return.", "confidence": "HIGH"}}, "R-32": {"low_charge": {"suction": "LOW", "discharge": "LOW", "superheat": "HIGH", "subcooling": "LOW", "threshold_35C": "Suction below 115 PSI, discharge below 370 PSI", "threshold_45C": "Suction below 140 PSI, discharge below 450 PSI", "notes": "Same pattern as R-22 but at higher absolute pressures. R-32 has higher GWP sensitivity — a small leak causes proportionally large charge loss. All R-32 units in Pakistan database are inverter-type; variable speed complicates pressure diagnosis (pressures vary with compressor speed). Use manufacturer''s diagnostic mode for inverter units rather than static gauge readings.", "confidence": "HIGH"}, "dirty_condenser": {"suction": "SLIGHTLY_HIGH", "discharge": "HIGH", "superheat": "LOW_TO_NORMAL", "subcooling": "SLIGHTLY_HIGH", "threshold_35C": "Discharge above 420 PSI (>5% above max baseline)", "threshold_45C": "Discharge above 510 PSI (>5% above max baseline)", "notes": "R-32 runs at higher discharge temperatures than R-22/R-410A — a dirty condenser at 45°C ambient in Pakistan can push discharge temps to dangerous levels (>120°C) and trip the high-pressure switch or thermistor protection. Inspect condenser first on any R-32 high-pressure fault.", "confidence": "HIGH"}, "overcharge": {"suction": "HIGH", "discharge": "HIGH", "superheat": "LOW_OR_ZERO", "subcooling": "HIGH", "threshold_35C": "Suction above 140 PSI, discharge above 420 PSI, subcooling >8°C", "threshold_45C": "Suction above 168 PSI, discharge above 510 PSI, subcooling >8°C", "notes": "R-32 is a mildly flammable (A2L) refrigerant. Overcharge risk includes compressor liquid slugging. Do NOT vent R-32 to atmosphere when removing overcharge — recover properly.", "confidence": "HIGH"}, "dirty_evaporator_restricted_airflow": {"suction": "LOW", "discharge": "LOW_TO_NORMAL", "superheat": "HIGH", "subcooling": "NORMAL", "threshold_35C": "Suction below 118 PSI, discharge below 380 PSI", "threshold_45C": "Suction below 142 PSI, discharge below 460 PSI", "notes": "Same pattern as R-22 — low suction from reduced evaporator load. For inverter R-32 units, the inverter may compensate by reducing compressor speed, masking the low-suction signature. Check filter and indoor coil directly.", "confidence": "HIGH"}}, "R-410A": {"low_charge": {"suction": "LOW", "discharge": "LOW", "superheat": "HIGH", "subcooling": "LOW", "threshold_35C": "Suction below 105 PSI, discharge below 340 PSI", "notes": "Same directional pattern as R-22. R-410A is an HFC blend — charge by weight for precision; superheat/subcooling method is secondary confirmation.", "confidence": "HIGH"}, "dirty_condenser": {"suction": "SLIGHTLY_HIGH", "discharge": "HIGH", "superheat": "LOW_TO_NORMAL", "subcooling": "SLIGHTLY_HIGH", "threshold_35C": "Discharge above 410 PSI (>5% above max baseline)", "notes": "R-410A is more sensitive to high-ambient condenser fouling than R-22 due to steeper pressure-temperature curve at high condensing temperatures.", "confidence": "HIGH"}, "overcharge": {"suction": "HIGH", "discharge": "HIGH", "superheat": "LOW_OR_ZERO", "subcooling": "HIGH", "threshold_35C": "Suction above 130 PSI, discharge above 410 PSI, subcooling >8°C", "notes": "Overcharge on R-410A can cause compressor valve damage very quickly due to liquid slugging. Recover immediately if suction reads >135 PSI with low superheat.", "confidence": "HIGH"}, "dirty_evaporator_restricted_airflow": {"suction": "LOW", "discharge": "LOW_TO_NORMAL", "superheat": "HIGH", "subcooling": "NORMAL", "threshold_35C": "Suction below 108 PSI, discharge below 355 PSI", "notes": "Same pattern as R-22 and R-32. In Pakistan, indoor coil fouling from dust/lint is the most common cause.", "confidence": "HIGH"}}}, "pakistan_specific_diagnostic_notes": ["At 45–52°C ambient (Multan, Jacobabad, interior Sindh), a ''normal'' system will show discharge pressures at the high end of spec range. Do not misdiagnose a hot-ambient high-pressure reading as a fault without checking ambient temp first.", "Compressor high-pressure cutouts (protectors) may trip on hot days (>48°C) even on properly charged, clean systems. Let the system cool before condemning the compressor.", "Pakistan grid voltage fluctuates significantly (180–240V in many cities). Low voltage causes high compressor amperage and elevated suction pressure. Check voltage at outdoor unit before charging.", "Refrigerant quality in Pakistan market is inconsistent — mixed or adulterated R-22 cylinders cause abnormal pressure-temperature relationships. If PT chart readings don''t match gauge pressures, suspect refrigerant purity.", "Suction lines in Pakistan installations are often too short (no elbows, runs under 1m) — superheat measured at the compressor port will be nearly identical to evaporator outlet superheat in these cases."]}'::jsonb
WHERE id IS NOT NULL OR true;


